const financeFilter={search:'',type:'',status:'',postable:''};
const financeMoney=value=>Number(value).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})+' BDT';
function financeHero(title,description,actions=''){return `<header class="fin-hero"><div><span class="eyebrow">FINANCE WORKSPACE</span><h1>${title}</h1><p>${description}</p></div><div class="fin-actions">${actions}</div></header>`;}
function financeCard(title,body,link='',subtitle=''){return `<section class="fin-card"><div class="fin-card-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${link}</div>${body}</section>`;}
function financeTable(headers,body,empty){return body?`<div class="fin-table-wrap"><table class="fin-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`:`<div class="fin-empty">${empty}</div>`;}
function renderFinanceHome(){const kpis=[['Open Periods','2','accounting periods accepting postings','periods'],['Draft Journals','7','unposted journal entries','journals?status=draft'],['Posted Today','14',"journals with today’s posting date",'journals?status=posted']];const banks=[['1110','Operating account','Bank','City Bank',248350.75],['1120','Settlement wallet','Wallet','bKash',42780.20]];const quick=[['Chart of Accounts','accounts','◫'],['Journals','journals','▤'],['Receivables','receivables','↗'],['Payables','payables','↙'],['Banking','banking','▥'],['Reports','reports','◩'],['User Guide','user-guide','▣'],['System Detail','system-detail','⚙']];return `<div class="finance-mock">${financeHero('Finance dashboard','Operational overview · as of 25 Sep 2026, 9:45 AM',`<button class="btn" data-fin-refresh>Refresh</button><a class="btn" href="#/app/dashboard">Back to workspace</a>`)}<div class="fin-kpis">${kpis.map(([label,value,note,path])=>`<a href="#/app/finance/${path}"><span>${label}</span><strong>${value}</strong><small>${note}</small><b>↗</b></a>`).join('')}</div><div class="fin-two">${financeCard('Receivables',`<div class="fin-ledger-line"><span>Outstanding</span><strong>${financeMoney(183420)}</strong></div><div class="fin-ledger-line overdue"><span><i></i>Overdue (3 invoices)</span><strong>${financeMoney(28450)}</strong></div>`,`<a href="#/app/finance/receivables">View all ↗</a>`)}${financeCard('Payables',`<div class="fin-ledger-line"><span>Outstanding</span><strong>${financeMoney(92840)}</strong></div><div class="fin-ledger-line overdue"><span><i></i>Overdue (2 bills)</span><strong>${financeMoney(13200)}</strong></div>`,`<a href="#/app/finance/payables">View all ↗</a>`)}</div>${financeCard('Bank Balances',`<div class="fin-bank-grid">${banks.map(([code,name,type,bank,balance])=>`<article><div><span>${code}</span><b>${type}</b></div><h3>${name}</h3><small>${bank}</small><strong>${financeMoney(balance)}</strong></article>`).join('')}</div>`,`<a href="#/app/finance/banking">Manage accounts ↗</a>`)}${financeCard('Quick Navigation',`<div class="fin-nav-grid">${quick.map(([label,path,icon])=>`<a href="#/app/finance/${path}"><span>${icon}</span><strong>${label}</strong><b>↗</b></a>`).join('')}</div>`)}</div>`;}
function financeAccountTree(){const byParent=new Map();for(const account of financeAccounts){const bucket=byParent.get(account.parent)||[];bucket.push(account);byParent.set(account.parent,bucket)}const rows=[];function visit(parent,depth){for(const account of byParent.get(parent)||[]){rows.push({...account,depth,children:(byParent.get(account.code)||[]).length});visit(account.code,depth+1)}}visit('',0);return rows}
function renderFinanceAccounts(){const rows=financeAccountTree().filter(row=>(!financeFilter.search||`${row.code} ${row.name} ${row.class}`.toLowerCase().includes(financeFilter.search.toLowerCase()))&&(!financeFilter.type||row.type===financeFilter.type)&&(!financeFilter.status||String(row.active)===financeFilter.status)&&(!financeFilter.postable||String(row.postable)===financeFilter.postable));const select=(key,options)=>`<select data-fin-filter="${key}">${options.map(([value,label])=>`<option value="${value}" ${financeFilter[key]===value?'selected':''}>${label}</option>`).join('')}</select>`;const body=rows.map(row=>`<tr><td><div class="fin-account-cell" style="--depth:${row.depth}"><span class="fin-account-mark ${row.postable?'':'header'}">${row.postable?'◦':'▦'}</span><div><a href="#/app/finance/accounts/${row.id}">${row.code} · ${esc(row.name)}</a><small>${row.children} child${row.children===1?'':'ren'}</small></div></div></td><td><span class="fin-pill">${row.type}</span></td><td>${row.class}</td><td>${row.parent?financeAccounts.find(a=>a.code===row.parent)?.name||row.parent:'Top level'}</td><td><span class="fin-pill ${row.active?'good':'muted'}">${row.active?'Active':'Inactive'}</span></td><td><div class="fin-flags">${[!row.postable?'Header':'',row.control?'Control':'',row.system?'System':'',row.posted?'Posted':''].filter(Boolean).map(flag=>`<span>${flag}</span>`).join('')}</div></td><td><a href="#/app/finance/accounts/${row.id}">View</a><a href="#/app/finance/accounts/${row.id}/edit">Edit</a></td></tr>`).join('');return `<div class="finance-mock">${financeHero('Chart of Accounts','Define postable leaf accounts and header accounts with reporting class, effective dates, and posting rules.',`<a class="btn primary" href="#/app/finance/accounts/new">New account</a><button class="btn" data-fin-refresh>Refresh</button>`)}${financeCard('Account hierarchy',`<div class="fin-filters"><label>Search<input data-fin-filter="search" value="${esc(financeFilter.search)}" placeholder="Search by code, name, or description"></label><label>Account type${select('type',[['','All account types'],['asset','Asset'],['liability','Liability'],['equity','Equity'],['revenue','Revenue'],['expense','Expense']])}</label><label>Status${select('status',[['','All statuses'],['true','Active only'],['false','Inactive only']])}</label><label>Posting mode${select('postable',[['','All posting modes'],['true','Postable only'],['false','Header only']])}</label><button class="btn primary" data-fin-search>Search</button></div>${financeTable(['Account','Type','Class','Parent','Status','Flags','Action'],body,'No accounts match the current filters.')}<div class="fin-count">${rows.length} of ${financeAccounts.length} accounts · Sample company: Stravix Group BD</div>`,`<span class="fin-count-chip">${financeAccounts.length} accounts</span>`,'Search and explore the ledger account structure.')}</div>`;}
const financeAccountTabs=[['overview','Overview'],['transactions','Transactions'],['subaccounts','Subaccounts'],['usage','Mappings & usage'],['reconciliation','Reconciliation'],['audit','Audit history']];
function renderFinanceAccountRecord(path){const create=path.endsWith('/new'),edit=path.endsWith('/edit'),id=path.split('/')[4],account=financeAccounts.find(row=>row.id===id);if(!create&&!account)return `<div class="finance-mock">${financeHero('Account not found','The sample chart does not contain this account.',`<a class="btn" href="#/app/finance/accounts">Back to accounts</a>`)}</div>`;if(create||edit)return renderFinanceAccountForm(account);const params=new URLSearchParams(location.hash.split('?')[1]||''),tab=params.get('tab')||'overview',tabs=financeAccountTabs.filter(([key])=>key!=='reconciliation'||account.code==='1110');const link=(target)=>`#/app/finance/accounts/${account.id}?tab=${target}`;let content='';if(tab==='overview')content=`<div class="fin-detail-grid">${[['Account type',account.type],['Reporting class',account.class],['Normal balance',account.type==='liability'||account.type==='revenue'?'Credit':'Debit'],['Parent account',account.parent?financeAccounts.find(a=>a.code===account.parent)?.name:'Top level'],['Company','Stravix Group BD'],['Currency restriction','Any currency'],['Cost center','Not required'],['Cash-flow category',account.type==='asset'?'Operating':'None'],['Effective from','01 Jan 2026'],['Effective to','—']].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`;else if(tab==='transactions')content=`<div class="fin-filters"><label>Search<input placeholder="Search journal, memo, or description"></label><label>Source type<input placeholder="Source type (optional)"></label><button class="btn" data-fin-search>Search</button><button class="btn" data-fin-export>Export CSV</button></div>${financeTable(['Date','Journal','Description','Source','Debit','Credit','Running balance','Action'],`<tr><td>25 Sep 2026</td><td><a href="#/app/finance/journals">JRN-0248</a></td><td>Customer collection · ${account.name}</td><td>Payment · PAY-2802</td><td>—</td><td>${financeMoney(8400)}</td><td>${financeMoney(account.balance)}</td><td><a href="#/app/finance/journals">View journal</a></td></tr>`,'No posted transactions match this period.')}<div class="fin-count">1 transaction · Page 1 of 1</div>`;else if(tab==='subaccounts'){const children=financeAccounts.filter(row=>row.parent===account.code);content=financeTable(['Account','Status','Opening','Debit','Credit','Closing','Action'],children.map(child=>`<tr><td><a href="#/app/finance/accounts/${child.id}">${child.code} · ${esc(child.name)}</a></td><td>${child.active?'Active':'Inactive'}</td><td>${financeMoney(child.balance)}</td><td>—</td><td>—</td><td>${financeMoney(child.balance)}</td><td><a href="#/app/finance/accounts/${child.id}">View</a></td></tr>`).join(''),'This account has no direct subaccounts.')}else if(tab==='usage')content=financeTable(['Category','Label','Status'],`<tr><td>Payment</td><td>${account.name} settlement mapping</td><td>Configured</td></tr>`,'No Finance mappings reference this account.');else if(tab==='reconciliation')content=financeTable(['Account','Status','Statement period','Closing balance','Matched / unmatched','Action'],`<tr><td><a href="#/app/finance/reconciliation">1110 · City Bank operating account</a></td><td>Imported</td><td>01–24 Sep 2026</td><td>${financeMoney(account.balance)}</td><td>38 / 2</td><td><a href="#/app/finance/reconciliation">Open</a></td></tr>`,'No reconciliation source is linked to this account.');else content=financeTable(['Date','Action','Actor','Details'],`<tr><td>18 Sep 2026, 10:25 AM</td><td>Updated</td><td>Farah Ahmed</td><td>Account notes reviewed</td></tr><tr><td>02 Jan 2026, 9:00 AM</td><td>Created</td><td>System</td><td>Opening chart setup</td></tr>`,'No account audit history is available.');return `<div class="finance-mock">${financeHero(`${account.code} · ${account.name}`,'Account detail, activity, hierarchy, and posting context.',`<span class="fin-hero-pill">${account.active?'Active':'Inactive'} · ${account.postable?'Postable':'Header account'}</span><a class="btn" href="#/app/finance/accounts">Back to accounts</a><a class="btn" href="#/app/finance/accounts/${account.id}/edit">Edit account</a>${account.postable?'<a class="btn primary" href="#/app/finance/journals">New journal entry</a>':''}`)}${financeCard('Account summary',`<div class="fin-period"><label>From date<input type="date" value="2026-09-01"></label><label>To date<input type="date" value="2026-09-25"></label><button class="btn" data-fin-period>Apply period</button></div><div class="fin-summary">${[['Opening balance',financeMoney(account.balance-8400)],['Total debit',financeMoney(0)],['Total credit',financeMoney(8400)],['Closing balance',financeMoney(account.balance)],['Posted transactions',account.posted?'1':'0'],['Last posted',account.posted?'25 Sep 2026':'—']].map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</div>`,'','Balances use posted journal activity for the selected period.')}${financeCard('Account workspace',`<nav class="fin-tabs">${tabs.map(([key,label])=>`<a class="${tab===key?'active':''}" href="${link(key)}">${label}</a>`).join('')}</nav><div class="fin-tab-context"><span>ACCOUNT WORKSPACE</span><h3>${tabs.find(([key])=>key===tab)?.[1]||'Overview'}</h3><p>Account configuration and posted activity for ${account.name}.</p></div>${content}`)}</div>`;}
function renderFinanceAccountForm(account){const edit=Boolean(account),value=(key,defaultValue='')=>esc(account?.[key]??defaultValue),textField=(label,key,placeholder,required=false)=>`<label>${label}${required?' *':''}<input data-fin-form="${key}" value="${value(key)}" placeholder="${placeholder}"></label>`,select=(label,key,items)=>`<label>${label}<select data-fin-form="${key}">${items.map(item=>`<option value="${item}" ${account?.[key]===item?'selected':''}>${item}</option>`).join('')}</select></label>`;return `<div class="finance-mock">${financeHero(edit?'Edit account':'New account',edit?'Update account classification and posting rules.':'Create a postable leaf account or a reporting header account.',`<a class="btn" href="#/app/finance/accounts">Back to accounts</a>`)}${account?.posted?'<div class="fin-alert">Posted account · Code, type, reporting class, parent, and postable status are locked because this account has posted entries.</div>':''}${financeCard('Account details',`<form class="fin-form" data-fin-account-form><div class="fin-form-grid">${textField('Account code','code','1000',true)}${textField('Account name','name','Cash in bank',true)}${textField('Local name','localName','Optional local-language name')}${select('Account type','type',['asset','liability','equity','revenue','expense'])}${textField('Reporting class','class','Current assets',true)}${select('Parent account','parent',['',...financeAccounts.filter(row=>!row.postable).map(row=>row.code)])}${select('Cash-flow category','cashFlow',['Operating','Investing','Financing','None'])}${select('Restricted currency','currency',['Any currency','BDT','USD'])}${select('Default tax code','tax',['None','VAT 15%','Zero rated'])}<label>Effective from<input type="date" value="2026-01-01"></label><label>Effective to<input type="date"></label></div><label>Description<textarea placeholder="Optional usage notes for accountants">${esc(account?.description||'')}</textarea></label><div class="fin-toggles"><label><input type="checkbox" ${account?.active!==false?'checked':''}> Active · Account can be selected when active</label><label><input type="checkbox" ${account?.postable!==false?'checked':''}> Postable · Allow journal lines to post</label><label><input type="checkbox"> Cost center · Require on every posting</label></div><div class="fin-form-actions"><a class="btn" href="#/app/finance/accounts">Cancel</a><button class="btn primary" type="submit">${edit?'Update account':'Create account'}</button></div></form>`,'','Identity, classification, posting rules, and optional tax or currency limits.')}</div>`;}
root.addEventListener('input',event=>{const key=event.target.dataset.finFilter;if(key)financeFilter[key]=event.target.value;});
root.addEventListener('change',event=>{const key=event.target.dataset.finFilter;if(key){financeFilter[key]=event.target.value;render();}});
root.addEventListener('click',event=>{if(event.target.closest('[data-fin-refresh]')){flash('Finance sample data refreshed.');return;}if(event.target.closest('[data-fin-search]')){render();return;}if(event.target.closest('[data-fin-export]')){flash('Sample account activity export prepared.');return;}if(event.target.closest('[data-fin-period]')){flash('Sample period applied.');return;}});
root.addEventListener('submit',event=>{if(!event.target.matches('[data-fin-account-form]'))return;event.preventDefault();const form=event.target,code=form.querySelector('[data-fin-form="code"]').value.trim(),name=form.querySelector('[data-fin-form="name"]').value.trim();if(!code||!name){flash('Enter an account code and name.');return;}const current=financeAccounts.find(row=>row.id===location.hash.split('/')[4]);if(current){current.name=name;current.class=form.querySelector('[data-fin-form="class"]').value;location.hash=`#/app/finance/accounts/${current.id}`;}else{const row={id:`ACC-${code}`,code,name,type:form.querySelector('[data-fin-form="type"]').value,class:form.querySelector('[data-fin-form="class"]').value,parent:form.querySelector('[data-fin-form="parent"]').value,active:true,postable:true,control:false,system:false,posted:false,balance:0};financeAccounts.push(row);location.hash=`#/app/finance/accounts/${row.id}`;}flash('Sample account saved in this browser preview.');});
